{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-8e3d2a31b838acb8","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Work-type-extracted enforcement deliverable: a general Implementation\n28\t     epic whose TITLE names an enforcement tool (lint rule, CI check,\n29\t     static-analysis check, validation harness, enforcement) that shares its\n30\t     `component` with at least one other non-docs Implementation epic is a\n31\t     work-type extraction — the deliverable must be divided per surface into\n32\t     the consuming epics' Scope/ACs, not carved into a standalone epic.\n33\t     Exempt when the tool is the component's only implementation work.\n34\t\n35\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n36\t\n37\tUsage:\n38\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n39\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n40\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n41\t\"\"\"\n42\t\n43\timport argparse\n44\timport os\n45\timport re\n46\timport sys\n47\t\n48\timport yaml\n49\t\n50\tSECTIONS = [(\"Description\", (\"description\",)),\n51\t            (\"Scope\", (\"scope\",)),\n52\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n53\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n54\t\n55\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n56\t\n57\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n58\t           \"repo-onboarding\")\n59\t\n60\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n61\t# way) — parity with the implementation_type_rules judge.\n62\tPARALLEL_PAIRS = {\n63\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n64\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n65\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n66\t}\n67\t\n68\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n69\t\n70\t# A general Implementation epic whose title matches this AND shares its\n71\t# component with another non-docs Implementation epic is a work-type\n72\t# extraction of a shared-surface enforcement deliverable (check 6).\n73\tENFORCEMENT_TITLE_RE = re.compile(\n74\t    r'\\b(lint|ci check|ci gate|static[- ]analysis|validation harness'\n75\t    r'|enforcement)\\b', re.I)\n76\t\n77\t\n78\tdef read_frontmatter(path):\n79\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n80\t    with open(path, encoding=\"utf-8\") as f:\n81\t        content = f.read()\n82\t    m = FRONTMATTER_RE.match(content)\n83\t    if not m:\n84\t        return {}, content\n85\t    try:\n86\t        data = yaml.safe_load(m.group(1))\n87\t    except yaml.YAMLError:\n88\t        return {}, content\n89\t    if not isinstance(data, dict):\n90\t        return {}, content\n91\t    return data, content[m.end():]\n92\t\n93\t\n94\tdef body_headings(body):\n95\t    heads = []\n96\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n97\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n98\t    return heads\n99\t\n100\t\n101\tdef load_epics(artifacts_dir, strat_id):\n102\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n103\t\n104\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n105\t    \"\"\"\n106\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n107\t    if not os.path.isdir(task_dir):\n108\t        return {}\n109\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n110\t    epics = {}\n111\t    for name in sorted(os.listdir(task_dir)):\n112\t        m = pat.match(name)\n113\t        if not m:\n114\t            continue\n115\t        path = os.path.join(task_dir, name)\n116\t        fm, body = read_frontmatter(path)\n117\t        epics[name[:-3]] = (path, fm, body)\n118\t    return epics\n119\t\n120\t\n121\tdef dependency_closure(start_key, deps):\n122\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n123\t    seen, stack = set(), list(deps.get(start_key, []))\n124\t    while stack:\n125\t        n = stack.pop()\n126\t        if n in seen or n not in deps:\n127\t            continue\n128\t        seen.add(n)\n129\t        stack.extend(deps[n])\n130\t    return seen\n131\t\n132\t\n133\tdef check(strat_id, artifacts_dir, components_path):\n134\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n135\t    probs = []\n136\t    epics = load_epics(artifacts_dir, strat_id)\n137\t    if not epics:\n138\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n139\t                % (strat_id, artifacts_dir)]\n140\t\n141\t    valid_components = set()\n142\t    if os.path.isfile(components_path):\n143\t        with open(components_path, encoding=\"utf-8\") as f:\n144\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n145\t    if not valid_components:\n146\t        probs.append(\"cannot read canonical component list %s — verify the \"\n147\t                     \"path before trusting component names\" % components_path)\n148\t\n149\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n150\t    comps, titles = {}, {}\n151\t    for key, (path, fm, body) in epics.items():\n152\t        name = key + \".md\"\n153\t        # 1. body sections (contract parity with the artifact judge)\n154\t        heads = body_headings(body)\n155\t        for want, aliases in SECTIONS:\n156\t            if not any(a in h for h in heads for a in aliases):\n157\t                probs.append(\"%s: body missing '%s' section (required \"\n158\t                             \"sections: Description, Scope, Acceptance \"\n159\t                             \"Criteria, HLR Traceability)\" % (name, want))\n160\t        # 2. component vocabulary\n161\t        comp = fm.get(\"component\")\n162\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n163\t                and comp.strip() not in valid_components:\n164\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n165\t                         \"canonical name (submit.py strips unknown names)\"\n166\t                         % (name, comp.strip(), components_path))\n167\t        # collect graph facts\n168\t        dl = fm.get(\"dependencies\")\n169\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n170\t            if isinstance(dl, list) else []\n171\t        is_branch[key] = \"BRANCH-\" in key\n172\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n173\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n174\t        comps[key] = comp.strip() if isinstance(comp, str) else \"\"\n175\t        it = fm.get(\"implementation_type\")\n176\t        itype[key] = it if it in IT_ENUM else None\n177\t        prio[key] = fm.get(\"priority\")\n178\t        titles[key] = fm.get(\"title\") if isinstance(fm.get(\"title\"), str) else \"\"\n179\t\n180\t    def kind(key):\n181\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n182\t        that is not type Implementation is never a parallel-rule party; an\n183\t        Implementation epic's kind is its implementation_type when that is a\n184\t        known label, else 'general'.\"\"\"\n185\t        if not is_impl[key]:\n186\t            return \"non-implementation\"\n187\t        return itype[key] or \"general\"\n188\t\n189\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n190\t    universe = [k for k in epics\n191\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n192\t    for k in sorted(epics):\n193\t        if not is_docs[k]:\n194\t            continue\n195\t        cl = dependency_closure(k, deps)\n196\t        missing = sorted(e for e in universe if e != k and e not in cl)\n197\t        if missing:\n198\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n199\t                         \"Implementation epic — add %s to its dependency chain\"\n200\t                         % (k, \", \".join(missing)))\n201\t\n202\t    # 4. Priority inheritance — enablers of P0 work must be P0\n203\t    for k in sorted(epics):\n204\t        if is_branch[k] or is_docs[k]:\n205\t            continue\n206\t        if prio.get(k) != \"P0\":\n207\t            continue\n208\t        # every main-plan, non-docs epic in k's closure enables P0 work\n209\t        cl = dependency_closure(k, deps)\n210\t        for t in sorted(cl):\n211\t            if is_branch[t] or is_docs[t]:\n212\t                continue\n213\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n214\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n215\t                             \"but is %s — raise it to P0 or restructure\"\n216\t                             % (t, prio.get(t), k, prio.get(t)))\n217\t\n218\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n219\t    #    pairs carry no dependencies edge in either direction (direct edges\n220\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n221\t    #    them; dependencies naming epics with no file cannot be judged).\n222\t    for k in sorted(epics):\n223\t        if kind(k) == \"docs-authoring\":\n224\t            continue\n225\t        for t in deps[k]:\n226\t            if t not in epics:\n227\t                continue\n228\t            pair = frozenset((kind(t), kind(k)))\n229\t            rule = PARALLEL_PAIRS.get(pair)\n230\t            if rule:\n231\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n232\t                             \"parallel; remove the dependencies edge and \"\n233\t                             \"express any coupling as an AC gate on the \"\n234\t                             \"dependent epic\"\n235\t                             % (rule, t, kind(t), k, kind(k)))\n236\t\n237\t    # 6. Work-type-extracted enforcement deliverable — a general\n238\t    #    Implementation epic titled as an en